import React, { useEffect, useState, useRef } from "react";
import "./Temp_Dashboard.css";
import "./This_tailwind.css"
import TrendlineBar from './PlotTrendLineBar';
//import BarHorizontal from "./PlotBarHorizontal";
import Trendline from './PlotTrendLine';
//import Bar from "./PlotBar";
//import Plot from 'react-plotly.js';
import Gadget from "./gadget";
import Plot from 'react-plotly.js';
import { useStateValue } from "../StateProvider";
import Moveable_button from "./Moveable_Button";
import { Face } from "three/examples/jsm/Addons.js";
function Temp_Dashboard() {
    const [{user, cond_test, user_email, user_color, test}, dispatch] = useStateValue();
    
  //https://martinco.pythonanywhere.com/api/today
    const [token, setToken] = useState(null);

    useEffect(() => {
  
      const savedToken = localStorage.getItem('firebases-token');
      setToken(savedToken);
      //console.log(savedCondition)
    
    })
    const fetchDatafunc  = async(url, dataset) => {
        try {
            const response = await fetch(url,{
                method: 'GET',
                headers: {
                  'Authorization': `Bearer ${token}`
                }
      
              });
            const jsonData = await response.json();
            dataset(jsonData);
        }
        catch(error){
            console.error('Erro fetching data:' , error);
        }
    };


    const [year_data, setYear_Data] = useState(null);
    //http://127.0.0.1:5000/api/year
    //https://martinco.pythonanywhere.com/api/year
    //https://martinco.pythonanywhere.com/api/year_new
    useEffect(() => {
        if(token){
            fetchDatafunc('https://martinco.pythonanywhere.com/api/year_new', setYear_Data);
 
        }
    },[token])
        

    const [order, setOrder] = useState();
    //http://127.0.0.1:5000//api/order_trend_dashboard
    useEffect(() => {
        if(token){
            fetchDatafunc('https://martinco.pythonanywhere.com/api/order_trend_dashboard', setOrder);
        }
    },[token])
  
    

    //http://127.0.0.1:5000/api/delivery_rate_over_time
    const [x_datadeliveryrate, setX_DataDeliveryRate] = useState();
    
    const [y_datadeliveryrate, setY_DataDeliveryRate] = useState();
        
    useEffect(() =>{
        if(token){

            const fetchData = async() => {
                try {
                    const response = await fetch('https://martinco.pythonanywhere.com/api/delivery_rate_over_time',
                        {
                            method: 'GET',
                            headers: {
                              'Authorization': `Bearer ${token}`
                            }
                  
                          }
                    );
                    const jsonData = await response.json();
                    setX_DataDeliveryRate(jsonData.Total);
                    setY_DataDeliveryRate(jsonData.Tatol);
                }
                catch(error){
                    console.error('Erro fetching data:' , error);
                }
            };
        
            fetchData();
        }
    },[token]);
   
    //https://martinco.pythonanywhere.com/api/year_items
    const [item_year, setItem_Year] = useState(2024);
   
    const handleItemYear = (event) => {
        setItem_Year(event.target.value);
    }

    const [item, setItem] = useState(null);
    useEffect(() => {
        if(token){
            fetchDatafunc('https://martinco.pythonanywhere.com/api/year_items', setItem);
        }
    },[token])
    //http://127.0.0.1:5000/api/top_5_vendor
    //https://martinco.pythonanywhere.com/api/top_5_vendor
    const [vendors, setVendor] = useState(null);
    useEffect(() => {
        if(token){
            fetchDatafunc('https://martinco.pythonanywhere.com/api/top_5_vendor', setVendor);
        }
    },[token])

    const [shipping_days, setShipping_Days] = useState(null);
    useEffect(() => {
        if(token){
            fetchDatafunc('https://martinco.pythonanywhere.com/api/date_ship', setShipping_Days);
        }
    },[token])

    const [temp, setTemp] = useState();
    const [control, setControl] = useState(false);


    const handleGraph1click = (e) => {

        const category = e.points[0].x;
        
        setTemp(category);
        setControl(true);
    }
    
    useEffect(() => {
        if (control !== false){
            //console.log(temp)
            setControl(false)
        }

    }, [control])

    const [hidden, setHidden] = useState(1);
    useEffect(() => {
        // Reset the state to the default value when the component mounts
        setHidden(1);
    }, []);

    const handleHidden = () => {
        if (hidden === 1){
            setHidden(0);
        }
        else{
            setHidden(1);
        }
    }
    
    useEffect(() => {

        let hide_button = document.getElementById('temp_dashboard_hidden_mode')
        let show_button = document.getElementById('temp_dashboard_show_mode')
        let hidden_card = document.getElementById('temp_dashboard_hidden_card')
        let show_card = document.getElementById('temp_dashboard_show_card')
        let show_card_2 = document.getElementById('temp_dashboard_show_card_2')

        if(hidden === 1 && hide_button && show_button && hidden_card && show_card)
        {
            //this is when hidden True
            //hide add
            hide_button.classList.add('hidden')
            hidden_card.classList.add('hidden')
            //hidden_card.classList.add('hidden_show')

            //hide remove
            show_card.classList.remove('nothing_hidden') 
            show_card_2.classList.remove('nothing_hidden') 
            show_button.classList.remove('hidden')  //once user enter Send_email, which will set the OTP code, it will remove the button away
        }
        else if (hidden !== 1 && hide_button && show_button && hidden_card && show_card){
            //this is when hidden false
            //show removal
            show_card.classList.add('nothing_hidden') 
            show_card_2.classList.add('nothing_hidden') 
            show_button.classList.add('hidden') //once user enter Send_email, which will set the OTP code, it will remove the button away

            //hide removal
            hide_button.classList.remove('nothing_hidden')
            hide_button.classList.remove('hidden')
            hidden_card.classList.remove('nothing_hidden') //once user enter Send_email, which will set the OTP code, it will remove the button away
            hidden_card.classList.remove('hidden') //once user enter Send_email, which will set the OTP code, it will remove the button away

        }
      },[hidden])
    

    const [requestor, setRequestor] = useState('');
      //the idea is when user input the parameter, then need to update the fetch request to extract the data from parameters, currently using the get method.
      //need to use the post method to update the parameter behind the backend.
      //requestor, vendor, status
      //

    if (vendors === null) {
        return <div>Loading...</div>
    }

    if (year_data === null) {
        return <div>Loading...</div>
    }
    
    if (shipping_days === null) {
        return <div>Loading...</div>
    }


  return (
    <>
    <div class='dashboard_body'>

        <div class="wrapper">
            <button className="filter" onClick={handleHidden}>
                Filter
            </button>
            <h2 id="temp_dashboard_hidden_mode" className="nothing_hidden">Panel</h2>

            <h2 id="temp_dashboard_show_mode" className="nothing">Dashboard</h2>
            <div className="wrapper-outside nothing_hidden" id="temp_dashboard_hidden_card">
                <form className="filter-form">
                        <div className="filter-field">
                            <div className="filter-title">
                                <p>Requestor</p>
                                <a className="filter-button">Show</a>
                            </div>
                            <input className="filter-input" id="1" type="text" value = {requestor} onChange={(e) => setRequestor(e.target.value)} placeholder="Type Here" required/>
                        </div>
                        <div className="filter-field">
                            <div className="filter-title">
                                <p>Vendor</p>
                                <a className="filter-button">Show</a>
                            </div>
                            <input className="filter-input" id="2" type="text" placeholder="Type Here" required/>
                        </div>
                        <div className="filter-field">
                            <div className="filter-title">
                                <p>Status</p>
                                <a className="filter-button">Show</a>
                            </div>
                            <input className="filter-input" id="3" type="text" placeholder="Type Here" required/>
                        </div>
                </form>
            </div>
            <div className="wrapper-outside nothing" id="temp_dashboard_show_card">
                <div className="container" >
                    <h3 className="temp-card-title ">Value and Quantity Trend Monthly</h3>
                    <div className="trendline temp-one">
                        {
                            Object.entries(year_data).map(([key,value]) => (
                                    <div className="temp-report-card" key={key}>
                                        <h3 className="card-title">{key}</h3>
                                        {test ? <h3 className="number">{value[String(test)]}</h3>
                                            : <h3 className="number">{value['total']}</h3>
                                        }
                                    </div>
                                ))
                        }
                    </div>
                
                </div>
                <div className="container" >
                    <h3 className="temp-card-title">Value and Quantity Trend Monthly</h3>
                    <div className="trendline">
                        {order && 
                                (
                                    order['2024'] && 
                                    (
                                    <Trendline xaxis = {order['2024'].month} yaxis ={order['2024'].order} xname ='Month' yname = 'Orders' name = 'Orders over Month' width = {350} height={300} axis_color = '#efefef'></Trendline>
                                    )
                                )
                            }
                    </div>
                
                </div>
                <div className="container" >
                    <h3 className="temp-card-title">Delivery Rate</h3>
                    <div className="trendline">
                        <Trendline xaxis = {x_datadeliveryrate} yaxis ={y_datadeliveryrate} xname ='Month' yname = 'Percentage' name = 'Delivery Rate over Month' width = {350} height={300} axis_color = '#efefef'></Trendline>
                    </div>
                
                </div>
            </div>
            <div className="wrapper-outside nothing" id="temp_dashboard_show_card_2">
                <div className="container">
                    <h3 className="temp-card-title">Average Shipping Days</h3>
                    <div className="trendline">
                        <Gadget className='data-delivery' min ={shipping_days.start} middle_1 = {shipping_days.mid_1} middle_2 = {shipping_days.mid_2} max ={shipping_days.end}/>

                    </div>
                
                </div>
                <div className="container">
                    <h3 className="temp-card-title">Value and Quantity Percentage Change Over Month</h3>
                    <div className="trendline">
                        {
                        item && 
                            (
                                item[item_year] && 
                                    ((
                                        <TrendlineBar xaxis = {item[item_year].Month} yaxis = {item[item_year].Items} ybar ={item[item_year].Percent_Change}  xname ='Month' yname = 'Items' name = 'Orders over Month' width = {350} height={300} axis_color = '#efefef'></TrendlineBar>

                                    ))
                            )
                        }
                    </div>
                
                </div>
                <div className="container">
                    <h3 className="temp-card-title">Top 5 vendors</h3>
                    <div className="trendline">
                        <table className="vendor_table temp-table">
                            <thead>
                                <tr>
                                    <th className="th-background">Vendor</th>
                                    <th className="th-background">Quantity</th>
                                    <th className="th-background">Spend</th>
                                </tr>
                            </thead>
                            <tbody>

                                {
                                Object.entries(vendors).map(([key,value]) => (
                                    <tr key={key}>
                                        <td>{key}</td>
                                        <td>{value.quantity}</td>
                                        <td>{value.value}</td>
                                    </tr>
                                ))
                                }
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    </div>
    </>
  )
}

export default Temp_Dashboard;
