import React, { useState } from "react";
import "./Credit_Card.css";
import { Link, useNavigate } from "react-router-dom";
import { signInWithEmailAndPassword } from "firebase/auth";
import { auth } from "../config/Firebase";
import { useStateValue } from "../StateProvider";

function Login_Card() {
  const navigate = useNavigate();
  const [inputs, setInputs] = useState({
    email: "",
    password: "",
  });

  const [{user_email}, dispatch] = useStateValue();


  const signIn = (e) => {
    e.preventDefault();

    signInWithEmailAndPassword(auth, inputs.email, inputs.password)
      .then(() => {

        localStorage.setItem('userEmail', inputs.email)
        navigate("/OTP_Glass");
        //navigate("/OTP_Auth");
      })
      .catch((error) => alert(error.message));
  };

  const register = () => {
    navigate("/register_card");
  };

  return (
    <div className="body">
        <div class="box">

  
  <div class="mdl">
  <div class="circles">
    <div class="circle circle-1"></div>
    <div class="circle circle-2"></div>
  </div>  
    <div class="card">

      <form>
        <div class="card-logo">
          <svg width="48px" height="48px" viewBox="0 0 64 64">
            <title>Group</title>
            <g id="Page-1" stroke="none" stroke-width="1" fill="none" fill-rule="evenodd">
              <g id="Group" fill="#FFFFFF">
                <circle id="Oval" cx="16" cy="16" r="16"></circle>
                <circle id="Oval" cx="16" cy="48" r="16"></circle>
                <circle id="Oval" cx="48" cy="16" r="16"></circle>
                <circle id="Oval" cx="48" cy="48" r="16"></circle>
              </g>
            </g>
          </svg>
          <h1 className="logo-SDI">SDI Inc.</h1>

        </div>
        <div class="card-number">
          <label>Email</label>
          <input className="login-input" id="card-number" placeholder="1234 1234 1234 1234" type="text" value={inputs.email}
            onChange={(e) =>
              setInputs((data) => ({ ...data, email: e.target.value }))
            }
          />
          <span class="underline"></span>

        </div>
        <div class="card-number">
          <label>Password</label>
          <input className="login-input" id="card-number" placeholder="**********" type="password"
            value={inputs.password}
            onChange={(e) =>
              setInputs((data) => ({ ...data, password: e.target.value }))
            }
            />
          <span class="underline"></span>

        </div>
        
        <div class="card-butt">
            
          <button
          type="submit"
          onClick={signIn}
          className="card-button">Sign In</button>

          <button onClick={register} className="card-button">Register</button>
      </div>
      </form>
    </div>
  </div>

        </div>

    </div>
  );
}

export default Login_Card;
